const section=(title,text,extra={})=>({title,text,...extra});
const chapter=(id,title,kicker,summary,structures,sections,extra={})=>({id,title,kicker,summary,structures,sections,...extra});
export const NEURON_COURSE={id:'c3',number:'03',title:'Neurones et signaux électriques',subtitle:'De la cellule au potentiel d’action et à son enregistrement',source:'./assets/cours-3.txt',chapters:[
chapter('c3-neurone','Les territoires du neurone','Réception, intégration et transmission','Suivre l’information dans une cellule, des dendrites aux terminaisons.',['neuron','dendrites','soma','initialSegment','axon','terminals'],[
section('Changer d’échelle','Le cerveau comporte des dizaines de milliards de neurones. Une estimation très citée est d’environ 86 milliards ; « 90 milliards » dans le cours est un arrondi, pas un comptage exact de chaque cerveau. Les neurones ont des formes et des connexions très variées.'),
section('Les dendrites et leurs épines','Les dendrites reçoivent de nombreux signaux synaptiques, excitateurs ou inhibiteurs. Certaines portent des épines dendritiques, petites protubérances participant à des synapses. Les ramifications et les propriétés de la cellule contribuent à ce qu’elle peut intégrer, sans relation simple entre nombre de branches et importance du neurone.'),
section('Le soma : entretien et intégration','Le soma contient notamment le noyau et l’ADN. L’expression des gènes passe par l’ARN et la production de protéines, nécessaires à l’entretien et au fonctionnement cellulaire. Le soma participe aussi à l’intégration des signaux ; cette intégration n’a pas lieu dans le soma seul.'),
section('Le segment initial','Dans de nombreux neurones, le potentiel d’action débute au segment initial de l’axone. Une forte densité de canaux Na⁺ voltage-dépendants y favorise le déclenchement du signal lorsque les conditions de seuil sont réunies.'),
section('Un axone, de nombreuses cibles','Un neurone typique possède un axone qui peut se ramifier. Le potentiel d’action se propage jusqu’aux terminaisons. Certains axones humains sont très longs. Dans une synapse chimique, les terminaisons libèrent un neurotransmetteur vers une cellule cible.',{precision:'Il existe des neurones sans axone individualisé. Les nombres de synapses et de partenaires varient fortement : « 1 000 à 10 000 » est un ordre de grandeur pédagogique, pas une règle pour tous les neurones.'})
],{figure:'neuron',exercise:'td',takeaway:'Dendrites → intégration → segment initial → axone → terminaisons.',sources:['cellCounts']}),
chapter('c3-glie','Les cellules gliales','Soutenir, myéliniser et surveiller','Distinguer astrocytes, oligodendrocytes et microglie.',['astrocyte','oligodendrocyte','microglia','myelin'],[
section('Des partenaires actifs','Les cellules gliales contribuent au fonctionnement du tissu nerveux. Certaines gardent une capacité de prolifération. Les trois catégories du cours ne représentent pas toutes les cellules non neuronales du cerveau.',{precision:'Le comptage souvent cité compare neurones et cellules non neuronales. Ces dernières comprennent notamment des cellules vasculaires : on ne peut pas les assimiler toutes à des cellules gliales ni fixer un nombre universel de 90 milliards de glies.'}),
section('Les astrocytes','Ils interagissent avec neurones, synapses et vaisseaux. Ils contribuent au soutien métabolique, à la régulation des ions et à la récupération de neurotransmetteurs. Leur implication dans l’utilisation du glucose et d’autres substrats ne signifie pas que toute l’énergie des neurones passe obligatoirement par eux.'),
section('La barrière hématoencéphalique','Les astrocytes participent à l’organisation et au maintien des propriétés de la barrière, avec d’autres cellules de l’unité neurovasculaire.',{precision:'La barrière physique repose principalement sur les cellules endothéliales des capillaires et leurs jonctions serrées. Les astrocytes la soutiennent ; ils ne constituent pas à eux seuls un mur étanche.'}),
section('Les oligodendrocytes','Dans le système nerveux central, ils forment la myéline autour de segments axonaux. Un oligodendrocyte peut myéliniser plusieurs segments, sur plusieurs axones. Dans le système nerveux périphérique, ce rôle est assuré par les cellules de Schwann.'),
section('La microglie','Elle assure des fonctions de surveillance immunitaire, de réponse aux lésions et de phagocytose de débris. Ses prolongements explorent le milieu ; les cellules peuvent aussi migrer selon le contexte. Son rôle dépasse le seul « nettoyage ».')
],{figure:'glia',exercise:'td',takeaway:'Astrocyte → milieu et échanges ; oligodendrocyte → myéline ; microglie → surveillance.',sources:['cellCounts','bloodBarrier'],table:{headers:['Cellule','Repère du cours'],rows:[['Astrocyte','Vaisseaux, synapses, milieu extracellulaire'],['Oligodendrocyte','Myéline dans le SNC'],['Microglie','Surveillance et réponses immunitaires']]}}),
chapter('c3-membrane','Comprendre le potentiel de membrane','Une différence entre intérieur et extérieur','Lire un voltage et distinguer dépolarisation, repolarisation et hyperpolarisation.',['membrane','ionChannels','sodium','potassium'],[
section('Quel voltage mesure-t-on ?','Le potentiel de membrane est défini ici par Vm = potentiel intérieur − potentiel extérieur. Une valeur de −70 mV signifie que l’intérieur est à un potentiel inférieur de 70 mV à la référence extérieure. La différence concerne la membrane ; l’intérieur du neurone n’est pas rempli uniquement de charges négatives.'),
section('La membrane et les canaux','La bicouche lipidique s’oppose au passage libre des ions chargés. Des protéines permettent leur transport : canaux et transporteurs. Un canal offre un passage sélectif ; il ne joue pas le même rôle qu’une pompe consommant de l’ATP.'),
section('Les concentrations ioniques','Dans les conditions habituelles, Na⁺ est plus concentré à l’extérieur et K⁺ à l’intérieur. Ce sont des gradients de concentration. Ils ne suffisent pas à déterminer le mouvement d’un ion : le voltage et l’ouverture de passages comptent aussi.'),
section('Dépolarisation','Vm devient moins négatif, ou plus positif : par exemple −70 → −60 → −50 mV. C’est une variation du potentiel. Une petite dépolarisation reste possible sans potentiel d’action.'),
section('Repolarisation et hyperpolarisation','La repolarisation ramène le potentiel vers sa valeur de repos après une dépolarisation. Une hyperpolarisation rend Vm plus négatif que sa référence de repos : par exemple −70 → −80 mV.',{precision:'−70 mV est une valeur typique du cours. Le repos varie selon la cellule et les conditions : les termes décrivent une variation ou une position par rapport à une référence, pas des valeurs fixes pour tous les neurones.'})
],{figure:'membrane',takeaway:'Vm compare intérieur et extérieur ; dépolariser ne signifie pas forcément déclencher un PA.',sources:['membranePhysics'],table:{headers:['Variation','Exemple si le repos est à −70 mV'],rows:[['Dépolarisation','−70 → −60 mV'],['Repolarisation','Retour vers −70 mV après une dépolarisation'],['Hyperpolarisation','−70 → −80 mV']]}}),
chapter('c3-equilibre','Forces ioniques, repos et pompe','Des gradients au voltage de repos','Comprendre ce qui fait bouger les ions et ce qui maintient leurs gradients.',['potassium','sodium','ionChannels','sodiumPump','membrane'],[
section('Deux forces à combiner','Le gradient chimique favorise le déplacement d’un ion vers le côté où il est moins concentré. La composante électrique dépend du signe de sa charge et du voltage. Le mouvement net résulte des deux : un ion ne sort ou n’entre pas uniquement parce qu’il est plus concentré d’un côté.'),
section('Le potentiel d’équilibre','Eion est le voltage auquel les composantes chimique et électrique se compensent pour cet ion. Un canal ouvert peut alors laisser des ions traverser dans les deux sens, sans flux net. L’équation de Nernst relie Eion aux concentrations, à la température et à la valence : Eion = (RT / zF) × ln([ion]extérieur / [ion]intérieur).'),
section('Ouvrir un canal tend à rapprocher Vm de Eion','À Vm = −70 mV et EK ≈ −90 mV, l’ouverture d’un canal K⁺ favorise une sortie nette de K⁺. Mais si Vm était plus négatif que EK, le mouvement net serait inversé. Le petit atelier permet de comparer ces situations.',{precision:'Les valeurs de Eion du tableau sont les repères approximatifs du cours. Elles dépendent des concentrations et des conditions ; ECl, notamment, peut varier fortement.'}),
section('Pourquoi le repos est-il proche de EK ?','Au repos, la membrane est souvent plus perméable au K⁺ qu’au Na⁺. Les conductances de fuite influencent donc fortement Vm. Une perméabilité à d’autres ions, notamment Na⁺ et Cl⁻ selon la cellule, contribue aussi au résultat. Le repos n’est pas simplement un équilibre du potassium seul.'),
section('La pompe Na⁺/K⁺','La Na⁺/K⁺-ATPase utilise de l’ATP. À chaque cycle, elle exporte 3 Na⁺ et importe 2 K⁺. Elle maintient les gradients malgré les échanges par les canaux et contribue au potentiel par son transport électrogène.',{precision:'La repolarisation rapide d’un PA vient surtout de l’inactivation des canaux NaV et des courants K⁺. La pompe entretient les gradients dans la durée ; elle ne réalise pas à elle seule la descente de chaque PA.'})
],{figure:'pump',lab:'ions',takeaway:'Canaux → mouvements selon les gradients ; pompe → maintien des gradients avec de l’ATP.',sources:['membranePhysics'],table:{headers:['Ion','Potentiel d’équilibre : repère du cours'],rows:[['K⁺','≈ −90 mV'],['Na⁺','≈ +60 mV'],['Cl⁻','≈ −80 mV, très variable'],['Ca²⁺','≈ +100 mV, selon les concentrations']]}}),
chapter('c3-action','Le potentiel d’action, phase par phase','Seuil et canaux voltage-dépendants','Relier la courbe de voltage à l’état des canaux NaV et KV.',['initialSegment','sodium','potassium','ionChannels','membrane'],[
section('Déclencher un signal','Une dépolarisation suffisante peut atteindre les conditions de seuil au segment initial. Le cours prend un repos vers −70 mV et un seuil vers −50 mV. Au-dessous du seuil, une variation graduée ne déclenche pas forcément de PA ; au-delà, un processus régénératif peut démarrer.'),
section('La montée : entrée de Na⁺','L’ouverture rapide de canaux Na⁺ voltage-dépendants favorise une entrée de Na⁺. La dépolarisation favorise à son tour l’ouverture de davantage de canaux : cette rétroaction positive explique la montée rapide du PA.'),
section('La descente : inactivation de NaV et sortie de K⁺','Les canaux NaV s’inactivent et les canaux K⁺ voltage-dépendants s’ouvrent avec retard. Dans les conditions du PA décrit, K⁺ sort et Vm redescend. Il faut retenir les deux mécanismes, pas uniquement la sortie de potassium.'),
section('L’après-hyperpolarisation','Des conductances K⁺ peuvent rester élevées un peu plus longtemps. Vm se rapproche alors davantage de EK et peut passer sous son niveau de repos. Le retour des conductances vers leur état de repos permet la récupération.'),
section('Tout ou rien, puis récupération','Dans des conditions comparables, dépasser le seuil déclenche un PA : augmenter le stimulus ne le transforme pas simplement en une pointe plus haute. Sa durée est de l’ordre de la milliseconde et son amplitude peut être de l’ordre de 100 mV, selon le neurone.',{precision:'Le seuil, la forme, la durée et l’amplitude ne sont pas identiques dans tous les neurones. Pendant la période réfractaire absolue, l’inactivation de NaV empêche un nouveau PA ; pendant la période relative, un stimulus plus fort peut être nécessaire.'})
],{figure:'actionPotential',lab:'ap',takeaway:'Na⁺ entre → montée ; NaV s’inactive et K⁺ sort → descente ; K⁺ persiste → hyperpolarisation.',sources:['membranePhysics','actionChannels']}),
chapter('c3-propagation','Coder et propager le signal','Fréquence, myéline et nœuds','Distinguer l’intensité d’un stimulus, l’amplitude d’un PA et sa vitesse de propagation.',['axon','myelin','ranvier','oligodendrocyte','terminals'],[
section('Intensité et fréquence','Dans de nombreuses situations, un stimulus plus intense augmente la fréquence des PA, plutôt que leur amplitude dans un même neurone. Le recrutement de neurones et l’organisation temporelle des décharges contribuent aussi au codage. La relation dépend du système étudié.'),
section('Régénérer le PA le long de l’axone','La variation électrique locale favorise l’activation des canaux du segment voisin. Le PA est ainsi régénéré : il ne s’agit pas d’un paquet d’ions sodium qui parcourt tout l’axone de bout en bout.'),
section('La conduction saltatoire','Dans un axone myélinisé, la myéline limite les fuites et modifie les propriétés électriques de la membrane. Le courant se propage sous la gaine ; le PA est régénéré surtout aux nœuds de Ranvier, riches en canaux adaptés. Le signal semble sauter d’un nœud au suivant.'),
section('Toutes les fibres n’ont pas la même vitesse','La myélinisation et le diamètre axonal influencent la vitesse. Certaines fibres motrices sont rapides ; certaines fibres de la douleur sont lentes et non myélinisées. Toutes les informations douloureuses ne passent toutefois pas par une seule catégorie de fibres.')
],{figure:'neuron',exercise:'td',takeaway:'Fréquence → nombre de PA par seconde ; myéline et diamètre → vitesse de conduction.',sources:['actionChannels']}),
chapter('c3-blocage','Que se passe-t-il si les canaux sont bloqués ?','Lidocaïne et tétrodotoxine','Utiliser deux exemples du cours pour comprendre l’excitabilité.',['ionChannels','sodium','axon','initialSegment'],[
section('Un canal nécessaire au signal','Si les courants Na⁺ nécessaires à la montée sont suffisamment empêchés, la génération ou la propagation des PA peut échouer. La communication avec les circuits situés en aval est alors modifiée.'),
section('La lidocaïne','Cet anesthésique local agit notamment sur les canaux Na⁺ voltage-dépendants. En inhibant la conduction dans les fibres concernées, elle peut empêcher le message issu de la zone anesthésiée d’être transmis normalement. L’effet dépend des fibres et des conditions.'),
section('La tétrodotoxine (TTX)','La TTX bloque certains canaux NaV. Elle peut perturber les commandes nerveuses des muscles et compromettre la respiration. Le cours l’utilise comme exemple d’une toxine agissant sur l’excitabilité.',{precision:'Tous les sous-types de canaux NaV n’ont pas la même sensibilité à la TTX ou à la lidocaïne. Le mécanisme général ne signifie donc pas que toutes les cellules ou tous les canaux sont bloqués de façon identique.'})
],{figure:'membrane',takeaway:'Empêcher les courants Na⁺ nécessaires peut empêcher la naissance ou la propagation du PA.',sources:['sodiumBlockers']}),
chapter('c3-enregistrer','Comment enregistrer ces signaux ?','Intracellulaire, patch-clamp et populations','Distinguer le voltage d’une cellule des signaux recueillis autour d’elle.',['membrane','ionChannels','electrodes','eeg'],[
section('Mesure intracellulaire','Une microélectrode permet de comparer le potentiel intérieur à une référence extérieure. Au repos, on peut mesurer une valeur proche de −70 mV dans l’exemple du cours. Deux électrodes dans un milieu extérieur homogène et au repos peuvent donner une différence proche de zéro ; ce n’est pas une règle en présence d’activité électrique.'),
section('Le patch-clamp','Une pipette forme un contact étanche avec une petite zone de membrane. Selon la configuration, on étudie les courants d’un canal, d’un fragment de membrane ou de la cellule entière.'),
section('Deux modes à distinguer','En voltage-clamp, on impose un potentiel et on mesure le courant nécessaire. En current-clamp, on impose un courant et on observe le potentiel, par exemple les PA.',{precision:'Le patch-clamp ne signifie pas toujours « contrôler le voltage ». La technique peut être utilisée dans ces deux modes, et dans plusieurs configurations.'}),
section('Mesure extracellulaire et populations','Une électrode extérieure capte des signaux liés à des courants dans son voisinage, sans entrer dans chaque cellule. Des dispositifs à plusieurs sites permettent d’étudier des populations lors de mouvements, de stimulations ou de tâches. Le signal extracellulaire ne correspond pas directement au Vm intracellulaire de −70 mV.'),
section('Interpréter des motifs d’activité','Des analyses recherchent des régularités entre les enregistrements et une tâche. Un motif observé renseigne sur l’activité enregistrée dans ce contexte ; il ne constitue pas une lecture universelle de la pensée.')
],{figure:'actionPotential',takeaway:'Intracellulaire → Vm ; voltage-clamp → courant à voltage imposé ; extracellulaire → activité voisine.',sources:['patchClamp'],table:{headers:['Mode ou méthode','Ce que l’on observe'],rows:[['Microélectrode intracellulaire','Potentiel de membrane'],['Voltage-clamp','Courant à potentiel imposé'],['Current-clamp','Potentiel à courant imposé'],['Extracellulaire','Signaux de courants et décharges à proximité']]}})
]};
